(()=>{'use strict';function draft(order={},designer={}){const value=v=>String(v??'').trim(),customer=value(order.customer)||'Customer';const gaps=[['quote','Reviewed scope and price'],['measurements','Sizing / measurements'],['due','Required date and feasible timeline'],['approval','Design approval'],['delivery','Delivery arrangements']].filter(([key])=>!value(order[key])).map(([,name])=>name);const closed=['Delivered','Closed'].includes(order.stage);const message=['Hello '+customer+',','Thank you for your interest in '+(value(designer.name)||'our fashion studio')+'.',value(order.request)?'Your request: '+value(order.request):'Please tell us which garment or design you have in mind.',value(order.quote)?'Scope / quote for review: '+value(order.quote):'We will prepare a quote after confirming your design, fit, materials and timing.',value(order.due)?'Requested date: '+value(order.due)+'. We will confirm feasibility before agreeing delivery.':'What date do you need the garment?',gaps.length?'Please help us confirm: '+gaps.join('; ')+'.':'Please review the recorded scope and let us know if anything needs to change.',value(order.next)?'Suggested next step: '+value(order.next):closed?'Let us know if you need aftercare or would like to discuss another design.':'May we agree a consultation to confirm the brief?',value(designer.name)||'Your fashion studio'].join('\n\n');return {message,gaps,stage:value(order.stage)||'Enquiry',paymentRecorded:!!value(order.payment),notice:'Draft from owner-entered records. Review price, scope, promises and customer details before sharing. Payment notes are not independently verified.'};}
window.bongaFashionCloser={draft};if(!document.getElementById('order-list'))return;document.addEventListener('fashion-review-closer',event=>{let base;try{base=JSON.parse(localStorage.getItem('zuxuru-fashion-service-v1'))||{};}catch{base={};}const order=(base.orders||[]).find(o=>o.id===event.detail?.id);if(!order){document.getElementById('status').textContent='Save this enquiry before preparing a sales brief.';return;}const result=draft(order,base.designer),el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};const dialog=el('dialog');dialog.style.cssText='background:#0a0a0c;color:#fff;width:min(760px,92vw);max-height:90vh;overflow:auto;border:1px solid #00ffff';const title=el('h2','Review customer sales brief'),stage=el('p','Recorded stage: '+result.stage),note=el('p',result.notice),label=el('label','Editable customer message'),text=el('textarea');text.rows=16;text.style.width='100%';text.value=result.message;text.maxLength=8000;label.append(text);const missing=el('p',result.gaps.length?'Confirm before agreement: '+result.gaps.join(' · '):'Core fields are recorded. Check their accuracy before agreement.');const payment=el('p',result.paymentRecorded?'Payment note saved. Verify funds and terms before treating the order as paid.':'No payment evidence recorded. This brief does not mark the customer as paid.');const follow=el('button','Review follow-up task'),download=el('button','Download reviewed message'),close=el('button','Close');follow.onclick=()=>{document.dispatchEvent(new CustomEvent('fashion-review-followup',{detail:{id:order.id,message:text.value}}));dialog.close();dialog.remove();};download.onclick=()=>{if(!text.value.trim())return;const u=URL.createObjectURL(new Blob([text.value],{type:'text/plain'}));const a=el('a');a.href=u;a.download='reviewed-customer-message.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};close.onclick=()=>{dialog.close();dialog.remove();};dialog.oncancel=()=>dialog.remove();dialog.append(title,stage,missing,payment,note,label,follow,download,close);document.body.append(dialog);dialog.showModal();text.focus();});
})();
